.rf-desc { position: absolute; inset-inline-start: 0; inset-inline-end: 0; top: 0; max-height: calc(100% - 48px); overflow-y: auto; padding-block: 6px 16px; padding-inline: 46px 16px; background: var(--rf-page); border-start-start-radius: 0; border-start-end-radius: 0; border-end-end-radius: 24px; border-end-start-radius: 24px; transform: translateY(-104%); transition: transform .32s cubic-bezier(0.22,1,0.36,1), box-shadow .32s; }
.rf-desc-wrap[data-open] .rf-desc { transform: none; box-shadow: 0 16px 40px rgba(0,0,0,.18); }
