.rf-desc-foot { display: flex; margin-top: 16px; margin-inline-start: -30px; }
.rf-desc-go { flex: 1; display: flex; align-items: center; justify-content: center; height: 44px; border-radius: 999px; background: var(--rf-fill); color: var(--rf-ink); font-size: 15px; font-weight: 600; text-decoration: none; }
.rf-desc-by { margin: 8px 0 0; font-size: 13px; line-height: 18px; color: var(--rf-muted); }
/* Help, at the card's foot: each row opens its sheet over the page. */
.rf-desc-help { margin-block: 16px 0; margin-inline: -30px 0; border-radius: 16px; background: var(--rf-sheet); overflow: hidden; }
.rf-help-row { position: relative; width: 100%; display: flex; align-items: center; gap: 12px; min-height: 48px; padding: 0 14px; border: 0; background: none; color: var(--rf-ink); font: inherit; font-size: 15px; font-weight: 600; text-align: start; cursor: pointer; -webkit-tap-highlight-color: transparent; }
