.rf-knob-icon { position: absolute; inset: 0; display: grid; place-items: center; transition: opacity .25s, transform .4s cubic-bezier(.34,1.56,.64,1); }
.rf-knob-before { opacity: 0; transform: rotate(-120deg) scale(.6); }
.rf-switch[data-view="before"] .rf-knob-before { opacity: 1; transform: none; }
.rf-switch[data-view="before"] .rf-knob-after { opacity: 0; transform: rotate(120deg) scale(.6); }

