@keyframes rf-lens-in { from { opacity: 0; scale: .85; } }

/* The vote at the page's foot: part of the page at rest, a sheet over it
   while its help or the header's menu is open. */
.rf-sheet { position: relative; z-index: 6; flex: none; overflow: hidden; border-start-start-radius: 20px; border-start-end-radius: 20px; border-end-end-radius: 0; border-end-start-radius: 0; background: var(--rf-sheet); box-shadow: 0 -8px 32px rgba(0,0,0,.18), inset 0 1px 0 rgba(255,255,255,.06); transition: height .26s cubic-bezier(0.22,1,0.36,1), background .22s, box-shadow .22s; }
