.rf-pair-btn { position: relative; flex: 1; min-width: 0; height: 44px; border: 0; border-radius: 999px; background: none; color: var(--rf-ink); display: flex; align-items: center; justify-content: center; font-size: 17px; font-weight: 600; cursor: pointer; transition: color .2s; }
.rf-pair-btn[aria-checked="true"] { color: var(--rf-page); }
.rf-pair-btn:disabled { opacity: .6; }
.rf-pair-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.rf-pair-mark { display: flex; width: 0; overflow: hidden; opacity: 0; transition: width .26s cubic-bezier(0.22,1,0.36,1), margin .26s cubic-bezier(0.22,1,0.36,1), opacity .2s; }
