.rf-pair[data-rf-voted] .rf-pair-div { opacity: 0; }
.rf-morph { position: relative; flex: none; width: 128px; height: 52px; padding: 0; border: 0; border-radius: 26px; overflow: hidden; background: var(--rf-fill); color: var(--rf-ink); cursor: pointer; transition: width .38s cubic-bezier(.34,1.2,.64,1), background .25s, color .25s; }
