.rf-morph[data-rf-morph="next"] .rf-morph-next { opacity: 1; transform: none; }
.rf-line { margin: 12px 4px 6px; font-size: 13px; line-height: 18px; color: var(--rf-muted); }
.rf-line-tight { margin: 6px 4px 0; }
.rf-sub { flex: none; display: flex; align-items: center; gap: 2px; margin-block: 10px 2px; margin-inline: -12px 0; }
.rf-sub button { width: 44px; height: 44px; flex: none; display: grid; place-items: center; border: 0; background: none; color: var(--rf-ink); cursor: pointer; }
.rf-sub h2 { margin: 0; font-size: 17px; font-weight: 600; line-height: 22px; }
.rf-body { flex: 1 1 auto; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 12px; padding: 2px 0 12px; }
.rf-note { margin: 0; font-size: 13px; line-height: 18px; color: var(--rf-muted); }
.rf-para { margin: 0; font-size: 15px; line-height: 21px; }
.rf-sect { margin: 6px 0 -4px; font-size: 12px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--rf-muted); }
.rf-facts { border-radius: 16px; background: var(--rf-fill); padding: 4px 14px; }
.rf-facts > div { display: flex; flex-direction: column; justify-content: center; min-height: 52px; border-bottom: 1px solid var(--rf-line); }
.rf-facts > div:last-child { border-bottom: 0; }
.rf-facts b { font-size: 15px; font-weight: 600; line-height: 20px; }
.rf-facts small { font-size: 13px; color: var(--rf-muted); }
.rf-link { align-self: flex-start; min-height: 44px; display: inline-flex; align-items: center; color: var(--accent); font-size: 15px; font-weight: 500; text-decoration: none; }
.rf-me { align-self: flex-end; max-width: 80%; padding: 10px 14px; border-start-start-radius: 18px; border-start-end-radius: 18px; border-end-end-radius: 4px; border-end-start-radius: 18px; background: #0a6ee0; color: #fff; font-size: 15px; line-height: 20px; white-space: pre-wrap; }
.rf-ai { align-self: flex-start; max-width: 88%; display: flex; flex-direction: column; gap: 6px; }
.rf-ai small { display: flex; align-items: center; gap: 6px; font-size: 12px; line-height: 16px; color: var(--rf-muted); }
.rf-ai small svg { width: 14px; height: 14px; }
.rf-ai p { margin: 0; padding: 10px 14px; border-start-start-radius: 18px; border-start-end-radius: 18px; border-end-end-radius: 18px; border-end-start-radius: 4px; background: var(--rf-fill); font-size: 15px; line-height: 20px; white-space: pre-wrap; }
.rf-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.rf-chip { height: 44px; padding: 0 13px; border: 0; border-radius: 999px; background: var(--rf-fill); color: var(--rf-ink); font-size: 15px; font-weight: 500; white-space: nowrap; cursor: pointer; }
.rf-chip[aria-checked="true"] { background: var(--rf-ink); color: var(--rf-page); }
.rf-ask-form { flex: none; display: flex; align-items: center; gap: 8px; margin: 0; padding: 4px 0 8px; }
.rf-ask-form input { flex: 1; min-width: 0; box-sizing: border-box; border: 0; background: var(--rf-fill); box-shadow: inset 0 0 0 1px var(--rf-line); color: var(--rf-ink); font-size: 16px; line-height: 22px; outline: 0; }
.rf-ask-form input { height: 44px; padding: 0 16px; border-radius: 999px; }
.rf-go { flex: none; height: 44px; padding: 0 20px; border: 0; border-radius: 999px; background: #0a6ee0; color: #fff; font-size: 15px; font-weight: 600; cursor: pointer; }
.rf-go:disabled { opacity: .5; cursor: default; }
.rf-go-wide { align-self: stretch; height: 48px; }
.rf-thread { min-height: 200px; }
@media (prefers-reduced-motion: reduce) {
  .rf-sheet, .rf-scrim, .rf-seam, .rf-cap, .rf-switch, .rf-knob, .rf-knob-icon, .rf-pair-thumb, .rf-pair-mark, .rf-morph, .rf-morph-in, .rf-why, .rf-tile, .rf-picto, .rf-gbar, .rf-veil-box, .rf-bar-toggle svg, .rf-desc, .rf-desc-dim { transition: none; }
  .rf-lens { animation: none; }
  .rf-claim { animation: none; }
}

/* From 768px the change page is a panel, not a phone page on a desktop.
   It starts under the app's header (the shell's own header tokens, as the
   rail does) and never covers it, 16px clear of it and of the window's
   foot. It is as tall as what it holds, up to that room, and past it the
   stage scrolls inside it. The vote sheet is its foot, right under the
   claim, not pinned to the bottom of the window. The pane behind it is
   dimmed (.rf-page-dim, not the sidebar or the header); a click there is
   Back. review-flow.tsx opens the card onto these corners (restRadius).
   A phone keeps the page above exactly as it was. */
.rf-page-dim { display: none; }
@media (min-width: 768px) {
  .rf-page-wrap {
    top: calc(var(--browser-banner-h, 0px) + var(--platform-header-h) + var(--platform-safe-top, 0px));
    --rf-room: calc(100dvh - var(--browser-banner-h, 0px) - var(--platform-header-h) - var(--platform-safe-top, 0px) - var(--platform-tabs-h, 0px) - 32px);
  }
  .rf-page-dim { display: block; position: absolute; inset: 0; background: rgba(0,0,0,.32); pointer-events: auto; }
  .rf-bar { padding-top: 0; }
  .dark .rf-page-dim { background: rgba(0,0,0,.56); }
  .rf-page { top: 16px; bottom: auto; max-height: var(--rf-room); border-radius: 20px; box-shadow: 0 0 0 1px var(--rf-line), 0 24px 64px rgba(0,0,0,.18); }
  .rf-stage { flex: 0 1 auto; }
  .rf-sheet { max-height: calc(var(--rf-room) - 52px); border-radius: 0; box-shadow: inset 0 1px 0 var(--rf-line); }
}

/* New Needs you (an experiment), pictures for every card: a drawn picture
   fills its card or hero; the shots run's own crop sits on a plate. */
.rf-hero-drawn { display: block; position: relative; overflow: hidden; }
.rf-plate-fill { position: static !important; display: block; width: 100%; height: 100%; object-fit: cover; object-position: center; transform: none !important; }
.rf-plate-strip { object-fit: contain; }
.rf-claim { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }

/* ── Review flow: drawn pictures (features/review-flow/illustrations.tsx) ──
   One outlined object per benefit or group decision, on the ground the caller
   paints. Sizes are set inline from the box; these rules are the fixed parts.
   The hero replays the sage part once (rf-ill-play), never with reduced motion. */
.rf-ill { position: relative; display: block; overflow: hidden; }
.rf-ill-stage { position: absolute; display: block; overflow: visible; }
.rf-ill-label { position: absolute; display: block; margin: 0; line-height: 1.25; font-family: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: rgba(27,27,29,.86); }
.rf-ill-area { color: rgba(27,27,29,.62); }
.rf-ill-token { position: absolute; left: 50%; transform: translateX(-50%); display: flex; align-items: stretch; border-radius: 999px; overflow: hidden; white-space: nowrap; line-height: 1; font-variant-numeric: tabular-nums; letter-spacing: -.005em; }
.rf-ill-token > span { display: flex; align-items: center; }
.rf-ill-before { background: #1b1b1d; color: #FFFEEA; font-weight: 500; }
.rf-ill-after { background: #A9CF97; color: #1b1b1d; font-weight: 700; }
@keyframes rf-ill-fill { 0%, 30% { fill: #FFFEEA; } 100% { fill: #A9CF97; } }
@keyframes rf-ill-pop { 0%, 30% { transform: scale(.92); } 70% { transform: scale(1.05); } 100% { transform: none; } }
.rf-ill-play .rf-ill-sage { animation: rf-ill-fill .84s cubic-bezier(0.22,1,0.36,1) both; }
.rf-ill-play .rf-ill-gain { transform-box: fill-box; transform-origin: center; animation: rf-ill-pop .84s cubic-bezier(0.22,1,0.36,1) both; }
@media (prefers-reduced-motion: reduce) {
  .rf-ill-play .rf-ill-sage, .rf-ill-play .rf-ill-gain { animation: none; }
}

/* New Needs you (an experiment), the title shot's plates: real pixels of the
   changed area and 16px of its surroundings, flat (no shadow, no card of
   their own), the house radius; a deck's back plates are plain tones. */
.rf-tplate { position: absolute; overflow: hidden; display: block; }
.rf-tplate img { position: absolute; display: block; max-width: none; }
.rf-tplate-pair img { position: static; width: 100%; height: 100%; object-fit: cover; object-position: center; }

/* ── Versions: switches and picks in the version dialogs ────────────────
   docs/plans/versions.md. "Get Tier list's updates" in the Make your own
   dialog (fork-app.tsx) and the Updates sheet's two switches
   (features/versions/updates-sheet.tsx): a row of words with the switch at
   its end, as the board filters dialog draws one, inside the hairline of
   the dialog's info box so it reads as one more thing about the version.
   The whole row is the switch's label. */
.fork-follow {
  display: flex; align-items: center; gap: 12px; padding: 10px 12px;
  border-radius: 8px; border: 1px solid var(--app-sheet-line); cursor: pointer;
}
.fork-follow-title { display: block; font-size: 14px; font-weight: 600; line-height: 19px; color: var(--text-primary); overflow-wrap: anywhere; }
.fork-follow-sub { display: block; margin-top: 2px; font-size: 12px; line-height: 16px; color: var(--text-muted); }
/* Suggest to <original>'s list of the version's own changes
   (dev-board/suggest-back-dialog.tsx): one tick box a change, the row its
   label, a hairline between rows, the box in the accent. */
.suggest-pick { padding: 4px 0; }
.suggest-pick ul { margin: 0; padding: 0; list-style: none; }
.suggest-pick li + li .suggest-pick-row { border-top: 1px solid var(--app-sheet-line); }
.suggest-pick-row { display: flex; align-items: flex-start; gap: 10px; padding: 8px 12px; cursor: pointer; }
.suggest-pick-box { width: 18px; height: 18px; margin-top: 1px; flex: none; accent-color: var(--accent); }
.suggest-pick-title { min-width: 0; font-size: 14px; font-weight: 600; line-height: 19px; color: var(--text-primary); overflow-wrap: anywhere; }

/* ── THE NEW LOOK, AN EXPERIMENT (Settings › Experimental, off by default) ──
   Every rule here is scoped to html[data-skin="brand"], which the head's
   window.Skin sets from the device's stored choice before this sheet
   applies; without it not one rule below matches. Light shell only, and not
   over a dark app either (:not(.dark), :not([data-app-tone="dark"])): dark
   is the standard dark either way.
   The look, from the brand-kit pass: a flat cream ground, without the grain,
   the star or the washes; Geist for every word; warm hairlines; where you
   are in ink on a pale blue pill with an ink edge; unread counts in ink; on
   a project's Hub, the actions raised by an ink edge and a hard shadow; a
   change's picture framed by a plain ink outline.
   Appended last on purpose. The declarations other rules count
   (--home-washes, --home-wallpaper, --dc-sheet-fill) are not redeclared:
   the ground and the bars are painted over them instead. */
@font-face {
  font-family: 'Geist';
  /* Absolute: the build-scoped copy of this sheet (/b/<sha>/css/app.css)
     serves only .js and .css, so a relative url would 404 there. A browser
     without the new look never matches a rule that names Geist, so it never
     downloads the file. */
  src: url('/fonts/geist/Geist-Variable.woff2') format('woff2');
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) {
  font-family: 'Geist', ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
  background-color: #fcfbf3;
  /* Cards are white on the cream ground. */
  --dc-sheet-solid: #ffffff;
  /* Where you are: ink on a pale blue pill with an ink edge. */
  --lit-ink: #111111;
  --lit-tint: #dcebfa;
  --lit-line: #111111;
  /* The header's own ink on the top-level screens. A project's bar sets
     its own on #platform-header (white on the project's colour). */
  --brand-ink: #111111;
  --brand-tint: #f1efe6;
  --brand-line: #e2dfcf;
}
/* Warm hairlines, unless high contrast asked for darker ones. */
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]):not([data-contrast="more"]) {
  --app-sheet-line: #e7e4d4;
}

/* THE GROUND. The wallpaper is drawn on <body> by the route rule (one id
   deep); `:has(#platform-tabs)` is always true in the shell and makes this
   rule one id deep as well, so it wins by its classes. The tile zoom paints
   the moving view from --un-zoom-bg, so it follows. --home-ground moves with
   it: the browser scroller paints the body from it (!important), and the
   launch cover and the washes end on it. The scroller's fixed layer repaints
   the wallpaper; it is flat here too. */
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) body:has(#platform-tabs) {
  --home-ground: #fcfbf3;
  --un-zoom-bg: #fcfbf3;
  background: #fcfbf3;
}
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) body::before {
  background: #fcfbf3;
}

/* THE BARS. On the top-level screens the header is a flat cream bar with a
   hairline foot and square corners, not the faked glass with the rounded
   notch; a project's bar (html[data-community-tint]) keeps its colour. The
   doubled id outranks the route rules (two ids deep) by its classes. The
   tab bar keeps its own layer, filled flat. */
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]):not([data-community-tint]) #platform-header#platform-header {
  background-color: #fcfbf3;
  clip-path: none;
  border-end-start-radius: 0;
  border-end-end-radius: 0;
  box-shadow: inset 0 -1px 0 #e7e4d4;
}
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]):not([data-community-tint]) #platform-header#platform-header::before {
  display: none;
}
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) .platform-tabs::before {
  background: #fcfbf3;
}
/* Unread conversations count in ink (the vote count keeps the accent). */
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) .platform-tab-badge {
  background: #111111;
  color: #fcfbf3;
}

/* A PROJECT'S HUB. Open app, Invite and the ⋯ beside them are raised: an
   ink edge and a hard shadow, pressed down a pixel when tapped. Open app
   takes the accent, the other two are white. */
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) .dev-ws-open-app[data-ws-community-open-app],
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) [data-ws-community-invite],
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) .dev-ws-plus-btn-hero {
  border: 1px solid #111111;
  box-shadow: 1.5px 2px 0 #111111;
}
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) .dev-ws-open-app[data-ws-community-open-app] {
  background: var(--accent);
  color: var(--accent-ink);
}
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) [data-ws-community-invite],
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) .dev-ws-plus-btn-hero {
  background: #ffffff;
  color: #111111;
}
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) .dev-ws-open-app[data-ws-community-open-app]:active,
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) [data-ws-community-invite]:active,
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) .dev-ws-plus-btn-hero:active {
  transform: translate(1px, 1px);
  box-shadow: 0.5px 1px 0 #111111;
}
/* For you: each row's glyph on its own pale colour, and the channel's
   unread count in ink. */
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) [data-ws-hub-needs] .dev-ws-foryou-row > :first-child {
  background: #fcfab3;
  color: #111111;
}
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) [data-ws-mine-card] > :first-child {
  background: #dcebfa;
  color: #111111;
}
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) [data-ws-channel="preview"] > :first-child {
  background: #e1efd9;
  color: #111111;
}
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) .dev-ws-foryou-pill[data-ws-channel-unread] {
  background: #111111;
  color: #fcfbf3;
}

/* PICTURES OF A CHANGE: a plain ink outline, drawn over the picture so an
   image filling the box does not hide it. */
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) .dev-ws-recent-pic,
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) .dev-ws-media-view {
  outline: 1px solid #111111;
  outline-offset: -1px;
}

/* HOME: warm hairlines on the app tiles and the community cards, and Join
   in ink. */
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) .app-icon-tile,
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) .home-discover-card {
  border-color: #e7e4d4;
}
html[data-skin="brand"]:not(.dark):not([data-app-tone="dark"]) .card-add-btn[data-join] {
  border-color: #111111;
  color: #111111;
  box-shadow: none;
}
